//! Parity and regression tests for the Echo-TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_echo_tts/`, generated by
//! `tools/gen_echo_tts_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference modules (tiny seeded EchoDiT, tiny
//! seeded Fish S1 DAC, PCA state) and records the byte-level text ids,
//! the encoded text state, the speaker latent path, the euler
//! trajectories (the recorded `mx.random.normal` draws are replayed
//! here), the PCA/codec waveform, and the flattening-point crop.

use std::collections::VecDeque;
use std::path::{Path, PathBuf};

use serde_json::Value;

use super::sampler::GaussianNoise;
use super::{GenerateControls, Model, ModelConfig};
use crate::codec::fish_s1_dac::FishS1Dac;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_echo_tts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn rel_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    let max = b.iter().fold(0.0f32, |acc, v| acc.max(v.abs()));
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
        / max
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum differences when the gates were frozen; assertions
/// use these values, not re-measured ones. The euler latent gate sits
/// just above the f32 accumulation drift over the sampled steps (the
/// timestep embedding's exp/cos drift feeds the conditioning); the
/// waveform gates are relative because the tiny codec's conv stacks
/// amplify absolute drift (the codec fixture family uses the same
/// convention); the state gates cover the attention reductions.
const LATENT_TOLERANCE: f32 = 1e-4;
const WAVEFORM_REL_TOLERANCE: f32 = 1e-5;
const STATE_TOLERANCE: f32 = 1e-5;

/// The recorded `mx.random.normal` draws replayed in reference order.
struct ReplayNoise {
    draws: VecDeque<(Vec<usize>, Vec<f32>)>,
}

impl ReplayNoise {
    fn from_trace(traces: &Value) -> Self {
        let draws: Vec<(Vec<usize>, Vec<f32>)> = traces["noise_draws"]
            .as_array()
            .expect("draws")
            .iter()
            .map(|draw| {
                (
                    draw["shape"]
                        .as_array()
                        .expect("shape")
                        .iter()
                        .map(|v| v.as_u64().expect("dim") as usize)
                        .collect::<Vec<_>>(),
                    f32_vec(&draw["values"]),
                )
            })
            .collect();
        Self {
            draws: VecDeque::from(draws),
        }
    }
}

impl GaussianNoise for ReplayNoise {
    fn normal(&mut self, n: usize) -> Vec<f32> {
        let (recorded, values) = self
            .draws
            .pop_front()
            .expect("the fixture ran out of recorded draws");
        assert_eq!(
            recorded.iter().product::<usize>(),
            n,
            "recorded draw size {recorded:?} does not match the request {n}"
        );
        values
    }
}

fn open_case(name: &str) -> Model {
    let mut model = Model::open(&testdata(name)).expect("family model loads");
    let codec = FishS1Dac::open(&testdata(&format!("{name}/codec"))).expect("codec loads");
    model.set_codec(codec);
    assert!(model.waveform_ready());
    model
}

fn controls(name: &str, traces: &Value, block_sizes: Option<Vec<usize>>) -> GenerateControls {
    let config = ModelConfig::from_json(&read_json(&testdata(&format!("{name}/config.json"))))
        .expect("config");
    let mut controls = GenerateControls::from_config(&config);
    // The case's own sampler values (the blockwise case overrides them).
    let sampler = &traces["sampler"];
    controls.sampler.num_steps = sampler["num_steps"].as_u64().unwrap() as usize;
    controls.sampler.cfg_scale_text = sampler["cfg_scale_text"].as_f64().unwrap() as f32;
    controls.sampler.cfg_scale_speaker = sampler["cfg_scale_speaker"].as_f64().unwrap() as f32;
    controls.sampler.cfg_min_t = sampler["cfg_min_t"].as_f64().unwrap() as f32;
    controls.sampler.cfg_max_t = sampler["cfg_max_t"].as_f64().unwrap() as f32;
    controls.sampler.truncation_factor = sampler["truncation_factor"].as_f64().map(|v| v as f32);
    controls.sampler.rescale_k = sampler["rescale_k"].as_f64().map(|v| v as f32);
    controls.sampler.rescale_sigma = sampler["rescale_sigma"].as_f64().map(|v| v as f32);
    controls.sampler.speaker_kv_scale = sampler["speaker_kv_scale"].as_f64().map(|v| v as f32);
    controls.sampler.speaker_kv_max_layers = sampler["speaker_kv_max_layers"]
        .as_u64()
        .map(|v| v as usize);
    controls.sampler.speaker_kv_min_t = sampler["speaker_kv_min_t"].as_f64().map(|v| v as f32);
    controls.sequence_length = Some(sampler["sequence_length"].as_u64().unwrap() as usize);
    controls.block_sizes = block_sizes;
    controls.speaker_audio_chunk_size = Some(4096);
    controls
}

/// Text ids/mask and the encoded text state against the recorded stages.
fn check_text_stage(name: &str, traces: &Value) {
    let text = &traces["text"];
    let want_ids = i32_vec(&text["ids"]);
    let want_mask: Vec<bool> = text["mask"]
        .as_array()
        .expect("mask")
        .iter()
        .map(|v| v.as_bool().expect("flag"))
        .collect();
    let batch = super::text::get_text_input_ids_and_mask(
        &[text["normalized"].as_str().expect("normalized")],
        Some(text["max_text_length"].as_u64().unwrap() as usize),
        false,
        false,
    );
    assert_eq!(batch.ids, want_ids, "{name}: text ids");
    assert_eq!(batch.mask, want_mask, "{name}: text mask");
    assert_eq!(
        batch.width as i64,
        text["token_count"].as_i64().unwrap(),
        "{name}: token count"
    );
    let model = open_case(name);
    let state = model
        .dit
        .text_state(&batch.ids, &batch.mask)
        .expect("text state");
    let diff = max_abs_diff(&state, &f32_vec(&traces["text_state"]));
    assert!(diff <= STATE_TOLERANCE, "{name}: text state diff {diff}");
    drop(model);
}

fn run_generation_case(name: &str, block_sizes: Option<Vec<usize>>) {
    let traces = read_json(&testdata(&format!("{name}/traces.json")));
    let model = open_case(name);
    check_text_stage(name, &traces);

    let ctrl = controls(name, &traces, block_sizes);
    let text = traces["text"]["normalized"].as_str().expect("normalized");

    // Latent trajectory on its own replayed noise sequence.
    let latents = model
        .generate_latents(text, None, &ctrl, &mut ReplayNoise::from_trace(&traces))
        .unwrap_or_else(|error| panic!("{name}: generate_latents failed: {error}"));
    let diff = max_abs_diff(&latents, &f32_vec(&traces["latents"]));
    assert!(diff <= LATENT_TOLERANCE, "{name}: latents diff {diff}");

    // End to end through the PCA/codec decode and crop.
    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(text, None, &ctrl, &mut noise)
        .unwrap_or_else(|error| panic!("{name}: generate failed: {error}"));
    assert!(
        noise.draws.is_empty(),
        "{name}: draws left unconsumed: {}",
        noise.draws.len()
    );
    assert_eq!(
        generated.latent_frames as i64,
        traces["latent_frames"].as_i64().unwrap(),
        "{name}: latent frames"
    );
    assert_eq!(
        generated.flattening_point as i64,
        traces["flattening_point"].as_i64().unwrap(),
        "{name}: flattening point"
    );
    assert_eq!(
        generated.token_count as i64,
        traces["text"]["token_count"].as_i64().unwrap(),
        "{name}: token count"
    );
    let diff = rel_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(
        diff <= WAVEFORM_REL_TOLERANCE,
        "{name}: waveform rel diff {diff}"
    );
    assert_eq!(
        generated.sample_rate as i64,
        traces["sample_rate"].as_i64().unwrap(),
        "{name}: sample rate"
    );
}

#[test]
fn greedy_generation_matches_the_reference_end_to_end() {
    run_generation_case("greedy_generate", None);
}

#[test]
fn blockwise_generation_matches_the_reference_end_to_end() {
    run_generation_case("blockwise_generate", Some(vec![8, 8, 8]));
}

#[test]
fn voice_clone_matches_the_reference_end_to_end() {
    let name = "voice_clone";
    let traces = read_json(&testdata(&format!("{name}/traces.json")));
    let model = open_case(name);
    check_text_stage(name, &traces);

    // The recorded reference waveform through the codec/PCA speaker
    // path, against the recorded latent and mask.
    let ref_audio = f32_vec(&traces["ref_audio"]);
    let speaker = &traces["speaker"];
    let codec = FishS1Dac::open(&testdata(&format!("{name}/codec"))).expect("codec loads");
    let pca = super::audio::PcaState::open(&testdata(&format!("{name}/pca_state.safetensors")))
        .expect("pca loads");
    let (latent, rows, mask) = super::audio::get_speaker_latent_and_mask(
        &codec,
        &pca,
        &ref_audio,
        model.config.max_speaker_latent_length,
        model.config.audio_downsample_factor,
        4096,
        false,
        model.config.dit.speaker_patch_size,
    )
    .expect("speaker latent");
    assert_eq!(rows * model.latent_size(), latent.len());
    let diff = max_abs_diff(&latent, &f32_vec(&speaker["latent"]));
    assert!(
        diff <= LATENT_TOLERANCE,
        "{name}: speaker latent diff {diff}"
    );
    let want_mask: Vec<bool> = speaker["mask"]
        .as_array()
        .expect("mask")
        .iter()
        .map(|v| v.as_bool().unwrap())
        .collect();
    assert_eq!(mask, want_mask, "{name}: speaker mask");

    let ctrl = controls(name, &traces, None);
    let text = traces["text"]["normalized"].as_str().expect("normalized");
    let mut noise = ReplayNoise::from_trace(&traces);
    let generated = model
        .generate(&text, Some(&ref_audio), &ctrl, &mut noise)
        .unwrap_or_else(|error| panic!("{name}: generate failed: {error}"));
    assert!(noise.draws.is_empty(), "{name}: draws left unconsumed");

    let diff = rel_diff(&generated.samples, &f32_vec(&traces["waveform"]));
    assert!(
        diff <= WAVEFORM_REL_TOLERANCE,
        "{name}: waveform rel diff {diff}"
    );
    assert_eq!(
        generated.flattening_point as i64,
        traces["flattening_point"].as_i64().unwrap()
    );
}

#[test]
fn codec_zq_roundtrip_matches_the_reference() {
    let name = "codec_zq";
    let traces = read_json(&testdata(&format!("{name}/traces.json")));
    let codec = FishS1Dac::open(&testdata(&format!("{name}/codec"))).expect("codec loads");
    let pca = super::audio::PcaState::open(&testdata(&format!("{name}/pca_state.safetensors")))
        .expect("pca loads");
    let wave = f32_vec(&traces["wave"]);

    // encode_zq against the reference continuous latents (both sides
    // channel-major [codec_dim, frames]).
    let (zq, frames) = codec.encode_zq(&wave).unwrap();
    assert_eq!(frames as i64, traces["zq_frames"].as_i64().unwrap());
    let diff = max_abs_diff(&zq, &f32_vec(&traces["zq"]));
    assert!(diff <= STATE_TOLERANCE, "encode_zq diff {diff}");

    // decode_zq back to samples.
    let decoded = codec.decode_zq(&zq, frames).unwrap();
    let diff = rel_diff(&decoded, &f32_vec(&traces["decoded"]));
    assert!(diff <= WAVEFORM_REL_TOLERANCE, "decode_zq rel diff {diff}");

    // The codes path still matches the codec fixture protocol.
    let (codes, code_len) = codec.encode(&wave).unwrap();
    assert_eq!(code_len as i64, traces["code_len"].as_i64().unwrap());
    let want_codes = i32_vec(&traces["codes"]);
    let flat: Vec<i32> = codes.concat();
    assert_eq!(flat, want_codes);

    // Crop math with a flattening tail: the point fires inside and the
    // reference 2048 factor keeps the whole tail-decoded waveform (the
    // tiny codec is far shorter than 14 * 2048 samples).
    let crop = &traces["crop"];
    let latent = f32_vec(&crop["latent"]);
    let rows = crop["latent_rows"].as_u64().unwrap() as usize;
    let fp = super::audio::find_flattening_point(&latent, rows, 8, 0.0, 20, 0.05);
    assert_eq!(
        fp as i64,
        crop["flattening_point"].as_i64().unwrap(),
        "flattening point"
    );
    let decoded = super::audio::ae_decode(&codec, &pca, &latent, rows).unwrap();
    let diff = rel_diff(&decoded, &f32_vec(&crop["decoded"]));
    assert!(
        diff <= WAVEFORM_REL_TOLERANCE,
        "crop decode rel diff {diff}"
    );
    let cropped = super::audio::crop_audio_to_flattening_point(&decoded, fp);
    let diff = rel_diff(&cropped, &f32_vec(&crop["cropped"]));
    assert!(diff <= WAVEFORM_REL_TOLERANCE, "crop rel diff {diff}");
}

#[test]
fn text_intake_matches_the_reference_table() {
    let table = read_json(&testdata("text_cases.json"));
    for case in table["cases"].as_array().expect("cases") {
        let raw = case["raw"].as_str().expect("raw");
        let want_normalized = case["normalized"].as_str().expect("normalized");
        let normalized = super::text::normalize_text_prompt(raw);
        assert_eq!(normalized, want_normalized, "normalization of {raw:?}");
        let batch = super::text::get_text_input_ids_and_mask(&[raw], None, true, false);
        assert_eq!(batch.ids, i32_vec(&case["ids"]), "ids of {raw:?}");
        let want_mask: Vec<bool> = case["mask"]
            .as_array()
            .expect("mask")
            .iter()
            .map(|v| v.as_bool().unwrap())
            .collect();
        assert_eq!(batch.mask, want_mask, "mask of {raw:?}");
    }
}

#[test]
fn config_parses_with_reference_defaults() {
    let value = read_json(&testdata("greedy_generate/config.json"));
    let config = ModelConfig::from_json(&value).expect("config");
    assert_eq!(config.model_type, "echo_tts");
    assert_eq!(config.sample_rate, 8000);
    assert_eq!(config.max_text_length, 64);
    assert_eq!(config.audio_downsample_factor, 2048);
    assert!(config.normalize_text);
    assert!(!config.delete_blockwise_modules);
    assert_eq!(config.pca_filename, "pca_state.safetensors");
    assert_eq!(config.dit.latent_size, 8);
    assert_eq!(config.dit.model_size, 32);
    assert_eq!(config.dit.num_layers, 2);
    assert_eq!(config.dit.speaker_patch_size, 2);
    assert_eq!(config.dit.timestep_embed_size, 16);
    assert_eq!(config.sampler.num_steps, 5);
    assert_eq!(config.sampler.cfg_scale_text, 3.0);
    assert_eq!(config.sampler.cfg_scale_speaker, 8.0);
    assert_eq!(config.sampler.cfg_min_t, 0.5);
    assert_eq!(config.sampler.cfg_max_t, 1.0);
    assert_eq!(config.sampler.sequence_length, 24);
    assert!(config.sampler.rescale_k.is_none());
    // The defaults dataclass matches the reference constants.
    let defaults = ModelConfig::default();
    assert_eq!(defaults.sample_rate, 44100);
    assert_eq!(defaults.max_text_length, 768);
    assert_eq!(defaults.dit.model_size, 2048);
    assert_eq!(defaults.dit.num_layers, 24);
    assert_eq!(defaults.dit.adaln_rank, 256);
    assert_eq!(defaults.sampler.num_steps, 40);
    assert_eq!(defaults.sampler.sequence_length, 640);
}

#[test]
fn euler_math_matches_the_reference_formulas() {
    // np.linspace(0.999, 0, num_steps + 1) over f32.
    let schedule = super::sampler::t_schedule(5);
    assert_eq!(schedule.len(), 6);
    assert!((schedule[0] - 0.999).abs() < 1e-6);
    assert!(schedule[5].abs() < 1e-6);
    assert!((schedule[1] - 0.7992).abs() < 1e-6);
    // _temporal_score_rescale at t = 0.5, k = 2, sigma = 1.
    let v = [1.0f32, -2.0];
    let x = [0.5f32, 0.25];
    let out = super::sampler::temporal_score_rescale(&v, &x, 0.5, 2.0, 1.0);
    // snr = 1, ratio = (1 + 1) / (1 / 2 + 1) = 4/3.
    let expect: Vec<f32> = v
        .iter()
        .zip(x)
        .map(|(&v, x)| 2.0 * ((4.0 / 3.0) * (0.5 * v + x) - x))
        .collect();
    for (got, want) in out.iter().zip(&expect) {
        assert!((got - want).abs() < 1e-6, "{got} vs {want}");
    }
    // At t = 1 the rescale is the identity.
    let out = super::sampler::temporal_score_rescale(&v, &x, 1.0, 2.0, 1.0);
    assert_eq!(out, v);
    // The timestep embedding is [cos, sin] stacked halves.
    let emb = super::dit::timestep_embedding(0.0, 8);
    assert_eq!(emb.len(), 8);
    assert!((emb[0] - 1.0).abs() < 1e-6);
    assert!(emb[4].abs() < 1e-6);
}

#[test]
fn generate_refuses_a_missing_codec() {
    let model = Model::open(&testdata("greedy_generate")).expect("model loads");
    let traces = read_json(&testdata("greedy_generate/traces.json"));
    let ctrl = controls("greedy_generate", &traces, None);
    let mut noise = super::sampler::SeededGaussian::new(0);
    let error = model
        .generate("Hello.", None, &ctrl, &mut noise)
        .unwrap_err();
    assert!(
        error.to_string().contains("set_codec"),
        "unexpected error: {error}"
    );
}

#[test]
fn blockwise_refuses_when_blockwise_modules_are_deleted() {
    // A config with delete_blockwise_modules refuses block sizes at the
    // sampler boundary; the loaded model has the modules, so the
    // refusal must come from the config flag, not the weights.
    let mut value = read_json(&testdata("greedy_generate/config.json"));
    value["delete_blockwise_modules"] = serde_json::json!(true);
    let config = ModelConfig::from_json(&value).expect("config");
    assert!(config.delete_blockwise_modules);
    let mut ctrl = GenerateControls::from_config(&config);
    ctrl.block_sizes = Some(vec![8]);
    // The same weight file opened with the stripped config refuses the
    // block sizes at the sampler boundary.
    let model = Model::open_with_config(&testdata("greedy_generate"), value).expect("model loads");
    assert!(!model.dit.blockwise_enabled());
    let mut noise = super::sampler::SeededGaussian::new(0);
    let error = model
        .generate_latents("Hello.", None, &ctrl, &mut noise)
        .unwrap_err();
    assert!(
        error.to_string().contains("blockwise generation requires"),
        "unexpected error: {error}"
    );
}

#[test]
fn zero_audio_downsample_factor_is_refused_at_load() {
    // A zero factor divides by zero in the speaker-latent conversion; the
    // config must fail at load with a BadConfig naming the field.
    let value = serde_json::json!({"audio_downsample_factor": 0});
    let err = ModelConfig::from_json(&value).expect_err("zero factor is refused");
    assert!(
        matches!(&err, crate::SpeechError::BadConfig { field, .. } if field == "audio_downsample_factor"),
        "unexpected error: {err}"
    );
}
